from collections import deque

def bfs_depth_n(graph, start, target_depth):
    """BFS to find nodes at exactly target_depth from start."""
    visited = set([start])
    queue = deque([(start, 0)])
    depth_nodes = {0: {start}}

    while queue:
        node, depth = queue.popleft()

        if depth >= target_depth:
            continue

        for neighbor in graph.get(node, []):
            if neighbor not in visited or depth + 1 == target_depth:
                if depth + 1 not in depth_nodes:
                    depth_nodes[depth + 1] = set()
                depth_nodes[depth + 1].add(neighbor)

                if depth + 1 < target_depth:
                    queue.append((neighbor, depth + 1))
                    visited.add(neighbor)

    return depth_nodes.get(target_depth, set())

# Actually, let me do a cleaner BFS that tracks depth properly
def bfs_exact_depth(graph, start, target_depth):
    """Find nodes at exactly target_depth from start using BFS."""
    if target_depth == 0:
        return {start}

    # Track visited nodes at each depth level
    current_level = {start}
    visited = {start}

    for depth in range(1, target_depth + 1):
        next_level = set()
        for node in current_level:
            for neighbor in graph.get(node, []):
                next_level.add(neighbor)
        current_level = next_level
        print(f"Depth {depth}: {sorted(current_level)}")

    return current_level

result = bfs_exact_depth(graph, start, 4)
print(f"\nNodes at exactly depth 4: {sorted(result)}")
